// Browser-only fixture of the actual emitted standalone viewer. No Website auth or DB.
import http from 'node:http';import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const stage='F:/VisibleMedicine/staging/20261023-fda-review-website',site=stage+'/website',phase=process.argv[2]??'browser',dir=stage+'/'+phase,read=p=>JSON.parse(fs.readFileSync(p)),registry=read(site+'/lib/clinical-review-reference-assets.json'),viewer=read(site+'/public/atlas-review-viewer/manifest.json'),sha=b=>createHash('sha256').update(b).digest('hex');assert(/^browser(?:-v\d+)?$/.test(phase));
assert(!fs.existsSync(dir));fs.mkdirSync(dir);const logs=[],map=new Map();for(const row of viewer.files){const file=site+'/public/atlas-review-viewer/'+row.path;assert.equal(sha(fs.readFileSync(file)),row.sha256);map.set('/atlas-review-viewer/'+row.path,file);}
