const server=http.createServer((req,res)=>{const url=new URL(req.url,'http://fixture.invalid');logs.push({at:new Date().toISOString(),method:req.method,path:url.pathname});res.setHeader('Cache-Control','no-store');
 if(['/fixture-embedded','/fixture-narrow'].includes(url.pathname)&&req.method==='GET'){const width=url.pathname==='/fixture-narrow'?480:660,q=new URLSearchParams({kind:'fda-shoulder',region:'shoulder',referenceRevision:registry.references[0].revision,structure:'vm:reference:fda-shoulder-fc9f3e56:scapula'});const html='<!doctype html><html><head><title>Emitted viewer · '+width+' × 470 fixture</title></head><body style="background:#e4eae6;font-family:Arial"><p>Isolated emitted-viewer layout fixture · not Website authentication</p><iframe title="Embedded reference test" style="width:'+width+'px;height:470px;border:1px solid #9ca" src="/atlas-review-viewer/index.html?'+q.toString()+'"></iframe></body></html>';res.setHeader('Content-Type','text/html; charset=utf-8');res.writeHead(200);res.end(html);return;}
 const file=map.get(url.pathname);if(!file||!['GET','HEAD'].includes(req.method)){res.writeHead(404);res.end('Fixture path not registered');return;}const bytes=fs.readFileSync(file),ext=path.extname(url.pathname),types={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json','.glb':'model/gltf-binary','.txt':'text/plain; charset=utf-8'};res.setHeader('Content-Type',types[ext]??'application/octet-stream');res.setHeader('Content-Length',bytes.length);res.writeHead(200);res.end(req.method==='HEAD'?undefined:bytes);});
server.listen(0,'127.0.0.1',()=>{const port=server.address().port,query=new URLSearchParams({kind:'fda-shoulder',region:'shoulder',referenceRevision:registry.references[0].revision,structure:'vm:reference:fda-shoulder-fc9f3e56:scapula'}),url='http://127.0.0.1:'+port+'/atlas-review-viewer/index.html?'+query;fs.writeFileSync(dir+'/STARTED.json',JSON.stringify({at:new Date().toISOString(),pid:process.pid,url,binding:viewer.websiteIntegrationSha256,mode:'actual-emitted-viewer-fixture',realWebsiteAuthentication:false,privateRecords:false,normalPreviewChanged:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({url,pid:process.pid,quit:'q'}));});
process.stdin.setEncoding('utf8');process.stdin.on('data',value=>{if(value.trim()==='q')server.close(()=>{fs.writeFileSync(dir+'/REQUESTS.json',JSON.stringify(logs,null,2)+'\n',{flag:'wx'});fs.writeFileSync(dir+'/TERMINAL.json',JSON.stringify({at:new Date().toISOString(),code:0,pid:process.pid,normalPreviewChanged:false},null,2)+'\n',{flag:'wx'});process.exit(0);});});
